import re
from ipaddress import IPv6Address, ip_address
from taf.sw.neat.interfaces.neat_v1 import NEATv1
from taf.sw.neat.services.auth.authorization import Authorization

class NEATVersionNotSupported(Exception):
    """ Raises when provided NEAT version is not supported. """


class ConnectionDetails(object):
    def __init__(self, host, username, password, timeout):
        self.protocol = 'https://'
        self.host = host
        self.port = '443'
        self.username = username
        self.password = password
        self.timeout = timeout

        self.base_url = '{protocol}{host}:{port}'.format(protocol=self.protocol,
                                                         host=self.host,
                                                         port=self.port)

    def make_configuration_host(self, original_endpoint):
        endpoint_match = re.match(r'^http.*localhost', original_endpoint)
        endpoint = original_endpoint.replace(endpoint_match.group(), '')
        original_endpoint = '{base_url}{endpoint}'.format(base_url=self.base_url,
                                                          endpoint=endpoint)
        return original_endpoint

    @staticmethod
    def format_host_for_base_url(host):
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(host), IPv6Address):
                return '[{}]'.format(host)
            else:
                return host
        except (ValueError, TypeError):
            return host

class SupportedNEATs(object):
    neat_v1 = NEATv1


class NEATProvider(object):
    @classmethod
    def create_neat(cls, host, username, password, neat_version='neat_v1', timeout=60):
        neat_type = getattr(SupportedNEATs, neat_version, None)

        if not neat_type:
            exception_message = 'Version {} of neat is not supported'.format(neat_type)
            raise NEATVersionNotSupported(exception_message)

        host = ConnectionDetails.format_host_for_base_url(host)
        token_details = Authorization.get_access_token_details(host, username, password)
        conn_details = ConnectionDetails(host, username, password, timeout)
        neat = neat_type(conn_details, token_details)

        return neat
